  "PortfolioPerformance": {
    "capitalGains": {
      "title": "Capital Gains",
      "value": "1,250,000.00 USD"
    },
    "interestIncome": {
      "title": "Interest Income",
      "value": "375,000.00 USD"
    },
    "totalReturn": {
      "title": "Total Return",
      "value": 8.5
    }
  }
